/*
 * AcousticLab service worker.
 *
 * Generated by scripts/build-sw.mjs — do not edit public/sw.js directly.
 *
 * Caching strategy, chosen so that a measurement never depends on the network:
 *
 *   install     precache every route document plus the manifest, icons and the
 *               compiled AudioWorklet. The worklet matters most: without it the
 *               app cannot measure at all, so it must never be a network miss.
 *   navigation  network first with a short timeout, falling back to the cached
 *               document, then to the cached start URL.
 *   /_next/static  cache first. These URLs contain a content hash, so a hit is
 *               always correct and a miss is always a genuinely new asset.
 *   RSC payloads  network first, cache fallback. Needed for client-side route
 *               transitions while offline.
 *   everything else same-origin  stale-while-revalidate.
 *
 * Cross-origin requests are never intercepted.
 */

const VERSION = '__SW_VERSION__';
const CACHE_NAME = 'acousticlab-' + VERSION;
const PRECACHE_URLS = __PRECACHE_URLS__;
const START_URL = '/';
const NAVIGATION_TIMEOUT_MS = 3500;

self.addEventListener('install', (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(CACHE_NAME);
      // Precache individually: one 404 must not abort the whole install.
      await Promise.all(
        PRECACHE_URLS.map(async (url) => {
          try {
            const response = await fetch(url, { cache: 'reload', credentials: 'same-origin' });
            if (response.ok) await cache.put(url, response);
          } catch {
            /* offline during install; runtime caching will pick it up */
          }
        })
      );
    })()
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const names = await caches.keys();
      await Promise.all(
        names.filter((name) => name.startsWith('acousticlab-') && name !== CACHE_NAME).map((name) => caches.delete(name))
      );
      if (self.registration.navigationPreload) {
        await self.registration.navigationPreload.disable().catch(() => undefined);
      }
      await self.clients.claim();
    })()
  );
});

self.addEventListener('message', (event) => {
  const data = event.data;
  if (!data) return;
  if (data.type === 'SKIP_WAITING') {
    self.skipWaiting();
  } else if (data.type === 'GET_VERSION') {
    event.source?.postMessage({ type: 'VERSION', version: VERSION });
  } else if (data.type === 'CLEAR_CACHES') {
    event.waitUntil(
      caches.keys().then((names) => Promise.all(names.map((name) => caches.delete(name))))
    );
  }
});

function isRscRequest(request) {
  const url = new URL(request.url);
  return url.searchParams.has('_rsc') || request.headers.get('RSC') === '1';
}

async function cacheFirst(request) {
  const cache = await caches.open(CACHE_NAME);
  const cached = await cache.match(request);
  if (cached) return cached;
  const response = await fetch(request);
  if (response.ok) cache.put(request, response.clone());
  return response;
}

async function staleWhileRevalidate(request) {
  const cache = await caches.open(CACHE_NAME);
  const cached = await cache.match(request);
  const network = fetch(request)
    .then((response) => {
      if (response.ok) cache.put(request, response.clone());
      return response;
    })
    .catch(() => null);
  if (cached) return cached;
  const response = await network;
  if (response) return response;
  return new Response('Offline and not cached', { status: 504, statusText: 'Offline' });
}

async function networkFirst(request, timeoutMs) {
  const cache = await caches.open(CACHE_NAME);
  try {
    const response = await (timeoutMs ? fetchWithTimeout(request, timeoutMs) : fetch(request));
    if (response && response.ok) {
      cache.put(request, response.clone());
      return response;
    }
    if (response) return response;
  } catch {
    /* fall through to the cache */
  }
  const cached = await cache.match(request);
  if (cached) return cached;
  throw new Error('offline');
}

function fetchWithTimeout(request, timeoutMs) {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error('timeout')), timeoutMs);
    fetch(request).then(
      (response) => {
        clearTimeout(timer);
        resolve(response);
      },
      (error) => {
        clearTimeout(timer);
        reject(error);
      }
    );
  });
}

async function handleNavigation(request) {
  try {
    return await networkFirst(request, NAVIGATION_TIMEOUT_MS);
  } catch {
    const cache = await caches.open(CACHE_NAME);
    const url = new URL(request.url);
    const cached = (await cache.match(url.pathname)) || (await cache.match(START_URL));
    if (cached) return cached;
    return new Response(
      '<!doctype html><meta charset="utf-8"><title>AcousticLab offline</title>' +
        '<body style="background:#080c12;color:#e2e8f0;font:16px system-ui;padding:2rem">' +
        '<h1>AcousticLab is offline</h1>' +
        '<p>This screen has not been cached yet. Reconnect once and it will be available offline afterwards.</p>' +
        '</body>',
      { status: 200, headers: { 'Content-Type': 'text/html; charset=utf-8' } }
    );
  }
}

self.addEventListener('fetch', (event) => {
  const request = event.request;
  if (request.method !== 'GET') return;

  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;
  // Never cache the service worker itself.
  if (url.pathname === '/sw.js') return;

  if (request.mode === 'navigate') {
    event.respondWith(handleNavigation(request));
    return;
  }

  if (isRscRequest(request)) {
    event.respondWith(
      networkFirst(request, NAVIGATION_TIMEOUT_MS).catch(
        () => new Response('', { status: 504, statusText: 'Offline' })
      )
    );
    return;
  }

  if (url.pathname.startsWith('/_next/static/')) {
    event.respondWith(cacheFirst(request));
    return;
  }

  event.respondWith(staleWhileRevalidate(request));
});
